CREATE TABLE IF NOT EXISTS report2_delivered_outcome_v2(sample_key TEXT PRIMARY KEY,generation TEXT NOT NULL,wave_id TEXT NOT NULL,direction TEXT NOT NULL,publication_id TEXT NOT NULL,dispatch_id TEXT NOT NULL,message_id INTEGER NOT NULL,anchor_ts INTEGER,anchor_price REAL,notional_usd REAL,status TEXT NOT NULL,created_ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS report2_liquidation_outcome_v2(outcome_id TEXT PRIMARY KEY,forecast_group_key TEXT NOT NULL,metric_kind TEXT NOT NULL CHECK(metric_kind IN ('zone_touch','direction_return','trade_scenario_outcome')),level_price REAL,reference_price REAL,direction TEXT NOT NULL,source_id TEXT NOT NULL,upstream_id TEXT NOT NULL,observed_ts INTEGER NOT NULL,horizon TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT,legacy_metric INTEGER NOT NULL DEFAULT 0,created_ts INTEGER NOT NULL);
